window.phIcon = function (name, cls) {
  var b = window.FOLEY_ICONS.ph[name];
  if (!b) return '';
  return '<svg class="ic ' + (cls || '') + '" viewBox="0 0 256 256" aria-hidden="true">' + b + '</svg>';
};
window.emojiIcon = function (ch, cls) {
  var b = window.FOLEY_ICONS.emoji[ch];
  if (!b) return '<span class="ic-text ' + (cls || '') + '">' + ch + '</span>';
  return '<svg class="ic ic-emoji ' + (cls || '') + '" viewBox="0 0 32 32" aria-hidden="true">' + b + '</svg>';
};
